function listProcess(text, opts){
  opts=opts||{}; var sep=opts.sep!=null?opts.sep:',';
  var items=String(text||'').split(sep);
  if(opts.trim!==false){ items=items.map(function(s){ return s.replace(/^\s+|\s+$/g,''); }); }
  if(opts.dropEmpty){ items=items.filter(function(s){ return s.length>0; }); }
  if(opts.unique){ var seen={}, u=[]; for(var i=0;i<items.length;i++){ if(seen[items[i]]) continue; seen[items[i]]=1; u.push(items[i]); } items=u; }
  if(opts.sort){ items.sort(opts.sort==='desc' ? function(a,b){ return a<b?1:(a>b?-1:0); } : function(a,b){ return a<b?-1:(a>b?1:0); }); }
  if(opts.quote){ items=items.map(function(s){ return '"'+s+'"'; }); }
  var out=opts.outSep!=null?opts.outSep:'\n';
  return {ok:true, items:items, count:items.length, text:items.join(out)};
}

var EXPORTS={listProcess:listProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ListForgePure = EXPORTS; }
